* { box-sizing: border-box; }

body {
     margin: 0;
     padding: 32px 16px;
     font-family: Arial, "Segoe UI", sans-serif;
     background: #0f172a;
     color: #e2e8f0;
}

.thu-vien {
     max-width: 1000px;

    margin: 0 auto;
}

.thu-vien h1 {
    text-align: center;
    font-size: 26px;
    margin: 0 0 6px;
}

.mo-ta {
    text-align: center;
    color: #94a3b8;
    font-size: 14px;
    margin: 0 0 26px;
}

.luoi-anh {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 18px;
}

figure {
    margin: 0;
    background: #1e293b;
    border-radius: 10px;
    overflow: hidden;
    box-shadow: 0 8px 20px rgba(0, 0, 0, 0.25);
}

figure img {
    width: 100%;
    height: 170px;
    object-fit: cover;
    display: block;
}

figcaption {

     padding: 10px 14px;
     font-size: 13px;
     color: #cbd5e1;
}

@media (max-width: 768px) {
     .luoi-anh { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 480px) {
     .luoi-anh { grid-template-columns: 1fr; }
}
